import re
E=open('../EDITS.md').read()
blocks=re.findall(r'### EDIT (.*?)\n<<<<<<< OLD\n(.*?)\n=======\n(.*?)\n>>>>>>> NEW',E,re.S)
B={n:(o,w) for n,o,w in blocks}
def rep(w,a,b):
    assert w.count(a)==1,(a[:60],w.count(a))
    return w.replace(a,b)
out=['# K15b referee: replacement edits for kings/theory/LOOPY.md\n',
'Five of the eight blocks of K15/EDITS.md are accepted unchanged (status row C4.7, section 3 text, 5.7 cylinder bullet, status row P3.2prime, section 7 dud bullet): their OLD text occurs exactly once in the current LOOPY.md and their NEW text is accurate. Three blocks are replaced below. Each OLD block occurs exactly once in the current LOOPY.md (checked by `verify/chk_edits.py`).\n']
o,w=B['C4.7 restated']
w=rep(w,"That is 80 runs, up to 105 million roots each: **0 over and 0 under roots**. This covers",
"That is 20 ranges, each run in both readings and with root passers excluded and allowed (80 table rows, up to 105 million roots a row). Only the 40 free-pass rows can output over: **0 over and 0 under roots** in them. In plain P the freezing move of an over group wins at once, so the 40 plain-P rows say nothing about over. The referee K15b rebuilt the classifier from the definitions (own C++ solver and move generator, no code shared with `grp.c`): it reproduces the frozen, dud, over and under counts of 16 of the 20 ranges in both readings (all seven cyl:8×6 ranges, both cyl:8×8 ranges, five of the seven cyl:7×6 ranges, both flat 7×6 ranges), with identical labels root by root in 12 runs; 0 over and 0 under (CHECKED-2). This covers")
w=rep(w,"It finds no over signature on 3 files with ≤ 3 + 3 pawns (cyl:8×6, 7×6) and 20 roots per board on 4 files with ≤ 2 + 2 pawns (10 groups per board, up to symmetry); `kp_p` beside up to 40 pawn contexts and then beside every assignment of one context file refutes all of them (COMPUTED-1).",
"It finds no over signature on 3 files with ≤ 3 + 3 pawns (cyl:8×6, 7×6). On 4 files with ≤ 2 + 2 pawns it lists 20 roots per board (10 groups), but K15's tempo solver is not plain P: it counts a stalemate as a loss and lets a tempo move be played in check, so its tempo-free values differ from plain P at 166 of 1,500 sampled roots (K15b, `ref3`). With plain-P rules the over signature has 4 roots on cyl:8×6 and 6 on cyl:7×6, all among K15's 20 (they include the two survivors below), so the counts of this census depend on the convention (COMPUTED-1, K15b). `kp_p` beside up to 40 pawn contexts and then beside every assignment of one context file refutes all of K15's candidates (COMPUTED-1).")
w=rep(w,"It labels Z_B (§5.7) dud in plain P.","It labels Z_B (§5.7) dud in plain P (K15b's own classifier agrees on flat 7×6, cyl:7×6 and cyl:8×6).")
w=rep(w,"fails at 3 of 130 on file f (cyl:8×6 and cyl:7×6; one of the three also solved by the independent solver `ref3`, CHECKED-2).","fails at 3 of 130 on file f (cyl:8×6 and cyl:7×6). K15b re-solved all 260 positions of cyl:8×6 (files f and g) with `ref3` against its own predictor of r(G ⊞ over_D): 130 of 130 agree on g, the same 3 of 130 differ on f (CHECKED-2).")
w=rep(w,"  - The scratch search of Appendix A could not have found either class (its classifier could not output dud or over, K15), so it was no evidence for the old first half. (Revised after K15, 2026-10-27; before, the first half rested on that search.)",
"  - The scratch search of Appendix A is no evidence for the old first half. Its script was not kept, so it cannot be re-run. Tests of its kind (one-ply: immediate promotion or passed pawn) label Z_B \"other\" and none of the 41 dud roots of flat 7×6 as dud (K15's `oneply.py`, not re-run by K15b), and K15's first classifier of this kind could never output dud. (Revised after K15 and K15b, 2026-10-27; before, the first half rested on that search.)")
out.append("### EDIT C4.7 restated\n<<<<<<< OLD\n"+o+"\n=======\n"+w+"\n>>>>>>> NEW\n")
o,w=B['section 8 item 2']
w=rep(w,"Beside contexts, P: 1,296 positions (every assignment of\n     one context file, both sides) and 640 random-context positions equal r(G ⊞ dud_D), 0 differ (COMPUTED-1; a 50-position sample re-solved with\n     `ref3`, CHECKED-2);",
"Beside contexts, P: 1,296 positions (every assignment of\n     one context file, both sides) equal r(G ⊞ dud_D), 0 differ, re-solved by the referee K15b with the independent solver `ref3` against its own predictor (CHECKED-2); 640 random-context positions equal it too, 0 differ (COMPUTED-1);")
w=rep(w,"K15's census finds 43 distinct dud groups on cyl:7×6, 40 on cyl:8×6, 25 on\n     cyl:8×8 and 9 on flat 7×6 (≤ 3 + 3 to ≤ 4 + 4 pawns, 3 to 5 files; dud in the empty context in plain P; up to file translation, mirror and colour flip).",
"K15's census finds dud groups (dud in the empty context in plain P) in ranges of ≤ 3 + 2 to ≤ 4 + 4 pawns on 3 to 5 files: K15 reports 43 distinct groups on cyl:7×6, 40 on cyl:8×6, 25 on\n     cyl:8×8 and 9 on flat 7×6. These counts are not invariants: K15 merged closures by their smallest state and then reduced one representative root by symmetry. K15b recounted from the whole closures (own solver; a group = a connected set of dud closures; up to file translation, mirror and colour flip): 24 on cyl:7×6, 23 on cyl:8×6, 14 on cyl:8×8 and 7 on flat 7×6 (74, 68, 40 and 10 before the symmetry reduction). All 108 listed groups of `K15/fin2/dud_groups.md` are dud in plain P by K15b's classifier, and exactly those marked A+B are dud against free passes (COMPUTED-1 for the counts, CHECKED-2 for the labels).")
out.append("### EDIT section 8 item 2\n<<<<<<< OLD\n"+o+"\n=======\n"+w+"\n>>>>>>> NEW\n")
o,w=B['Appendix A group search']
w=rep(w,"**Withdrawn (revised after K15, 2026-10-27):** the classifier of this scratch search could not output dud\n    (a side counted as having a shuttle only if the opponent was frozen, so both sides never had one at once; its over test skipped pawn moves),\n    so the statement was no evidence. K15's exact census finds dud groups on both cylinders and no over group (§5.7, §8 item 2, Conjecture 4.7).",
"**Withdrawn (revised after K15 and K15b, 2026-10-27):** this scratch search used one-ply tests and its script was not kept. One-ply tests of that kind label Z_B \"other\" and find none of the 41 dud roots of flat 7×6 (K15's `oneply.py`; K15's first classifier of this kind could never output dud, because a shuttle needed a frozen opponent), so the statement was no evidence. K15's exact census, rebuilt by K15b, finds dud groups on both cylinders and no over group (§5.7, §8 item 2, Conjecture 4.7).")
out.append("### EDIT Appendix A group search\n<<<<<<< OLD\n"+o+"\n=======\n"+w+"\n>>>>>>> NEW\n")
open('EDITS.md','w').write('\n'.join(out))
